# name: utterance_all_true_vs_subset_true_rich_singleton_probe_rating_diff
# description: On utterance trials where second_probe is a true singleton with at least 3 features, mean second_rating when the word is true of all objects (with one singleton) minus when it is true of a proper subset including a 1-feature object.
def test_statistic(df):
    utt_df = df[df["heard"].notna()]
    if utt_df.empty:
        return 0.0
    triples = utt_df[["objects", "heard", "second_probe"]].drop_duplicates()
    group_map = {}
    for obj_str, h_val, prb_val in zip(triples["objects"], triples["heard"], triples["second_probe"]):
        h = int(h_val)
        prb = int(prb_val)
        objs = np.asarray(json.loads(obj_str), dtype=int)
        n_obj = len(objs)
        truth = objs[:, h] == 1
        diff = np.abs(objs[:, None, :] - objs[None, :, :]).sum(axis=2)
        is_sing = (diff == 0).sum(axis=1) == 1
        fcnt = objs.sum(axis=1)
        if is_sing[prb] and truth[prb] and fcnt[prb] >= 3:
            if truth.sum() == n_obj and is_sing.sum() == 1:
                group_map[(obj_str, h, prb)] = 1
            elif truth.sum() < n_obj and np.any(truth & (fcnt == 1)):
                group_map[(obj_str, h, prb)] = -1
    if not group_map:
        return 0.0
    keys = list(zip(utt_df["objects"], utt_df["heard"].astype(int), utt_df["second_probe"].astype(int)))
    grp = np.array([group_map.get(k, 0) for k in keys], dtype=int)
    ratings = utt_df["second_rating"].to_numpy().astype(float)
    m1 = grp == 1
    m2 = grp == -1
    if not np.any(m1) or not np.any(m2):
        return 0.0
    return float(ratings[m1].mean() - ratings[m2].mean())

# name: all_true_utterance_rich_singleton_choice_rate
# description: On 4-object utterance trials where the heard word is true of every object and one unique singleton has strictly more features than the three identical clones, the rate of choosing the singleton.
def test_statistic(df):
    utt_df = df[df["heard"].notna()]
    if utt_df.empty:
        return 0.0
    pairs = utt_df[["objects", "heard"]].drop_duplicates()
    target_map = {}
    for obj_str, h_val in zip(pairs["objects"], pairs["heard"]):
        h = int(h_val)
        objs = np.asarray(json.loads(obj_str), dtype=int)
        if len(objs) != 4:
            continue
        truth = objs[:, h] == 1
        if not np.all(truth):
            continue
        diff = np.abs(objs[:, None, :] - objs[None, :, :]).sum(axis=2)
        is_sing = (diff == 0).sum(axis=1) == 1
        if is_sing.sum() == 1:
            sing_idx = int(np.where(is_sing)[0][0])
            fcnt = objs.sum(axis=1)
            clone_fcnt = fcnt[~is_sing][0]
            if fcnt[sing_idx] > clone_fcnt:
                target_map[(obj_str, h)] = sing_idx
    if not target_map:
        return 0.0
    keys = list(zip(utt_df["objects"], utt_df["heard"].astype(int)))
    choices = utt_df["choice"].to_numpy()
    vals = [float(c == target_map[k]) for k, c in zip(keys, choices) if k in target_map]
    if not vals:
        return 0.0
    return float(np.mean(vals))

# name: utterance_sparse_singleton_vs_rich_clones_clone_choice_rate
# description: On utterance trials where the heard word applies to one unique singleton and at least two identical clones with strictly more features than the singleton, the rate of choosing one of the true clones.
def test_statistic(df):
    utt_df = df[df["heard"].notna()]
    if utt_df.empty:
        return 0.0
    pairs = utt_df[["objects", "heard"]].drop_duplicates()
    clone_sets = {}
    for obj_str, h_val in zip(pairs["objects"], pairs["heard"]):
        h = int(h_val)
        objs = np.asarray(json.loads(obj_str), dtype=int)
        truth = objs[:, h] == 1
        diff = np.abs(objs[:, None, :] - objs[None, :, :]).sum(axis=2)
        is_sing = (diff == 0).sum(axis=1) == 1
        fcnt = objs.sum(axis=1)
        true_sing = np.where(truth & is_sing)[0]
        true_clones = np.where(truth & (~is_sing))[0]
        if len(true_sing) == 1 and len(true_clones) >= 2:
            if np.all(fcnt[true_clones] > fcnt[true_sing[0]]):
                clone_sets[(obj_str, h)] = set(int(i) for i in true_clones)
    if not clone_sets:
        return 0.0
    keys = list(zip(utt_df["objects"], utt_df["heard"].astype(int)))
    choices = utt_df["choice"].to_numpy()
    vals = [float(c in clone_sets[k]) for k, c in zip(keys, choices) if k in clone_sets]
    if not vals:
        return 0.0
    return float(np.mean(vals))

# name: chain_utterance_max_feature_competitor_choice_rate
# description: On utterance trials where all objects are unique singletons and every object satisfying the heard word has at least 2 features, the rate of choosing the true object with the maximum feature count.
def test_statistic(df):
    utt_df = df[df["heard"].notna()]
    if utt_df.empty:
        return 0.0
    pairs = utt_df[["objects", "heard"]].drop_duplicates()
    target_map = {}
    for obj_str, h_val in zip(pairs["objects"], pairs["heard"]):
        h = int(h_val)
        objs = np.asarray(json.loads(obj_str), dtype=int)
        diff = np.abs(objs[:, None, :] - objs[None, :, :]).sum(axis=2)
        is_sing = (diff == 0).sum(axis=1) == 1
        if not np.all(is_sing):
            continue
        truth = objs[:, h] == 1
        fcnt = objs.sum(axis=1)
        true_fcnts = fcnt[truth]
        if len(true_fcnts) >= 2 and true_fcnts.min() >= 2 and true_fcnts.max() > true_fcnts.min():
            max_f = true_fcnts.max()
            target_map[(obj_str, h)] = set(int(i) for i in np.where(truth & (fcnt == max_f))[0])
    if not target_map:
        return 0.0
    keys = list(zip(utt_df["objects"], utt_df["heard"].astype(int)))
    choices = utt_df["choice"].to_numpy()
    vals = [float(c in target_map[k]) for k, c in zip(keys, choices) if k in target_map]
    if not vals:
        return 0.0
    return float(np.mean(vals))

# name: prior_sparse_vs_rich_singleton_choice_diff
# description: On prior trials (heard is NaN) with one unique singleton and N-1 identical clones, the rate of choosing the singleton when it has fewer features than the clones minus when it has more features than the clones.
def test_statistic(df):
    prior_df = df[df["heard"].isna()]
    if prior_df.empty:
        return 0.0
    unique_objs = prior_df["objects"].unique()
    scene_info = {}
    for obj_str in unique_objs:
        objs = np.asarray(json.loads(obj_str), dtype=int)
        n_obj = len(objs)
        diff = np.abs(objs[:, None, :] - objs[None, :, :]).sum(axis=2)
        is_sing = (diff == 0).sum(axis=1) == 1
        if is_sing.sum() == 1:
            sing_idx = int(np.where(is_sing)[0][0])
            fcnt = objs.sum(axis=1)
            clone_fcnt = fcnt[[i for i in range(n_obj) if i != sing_idx][0]]
            if fcnt[sing_idx] < clone_fcnt:
                scene_info[obj_str] = (1, sing_idx)
            elif fcnt[sing_idx] > clone_fcnt:
                scene_info[obj_str] = (-1, sing_idx)
    if not scene_info:
        return 0.0
    grp = prior_df["objects"].map(lambda s: scene_info.get(s, (0, -1))[0]).to_numpy()
    target = prior_df["objects"].map(lambda s: scene_info.get(s, (0, -1))[1]).to_numpy()
    chose_sing = (prior_df["choice"].to_numpy() == target).astype(float)
    sparse_mask = grp == 1
    rich_mask = grp == -1
    if not np.any(sparse_mask) or not np.any(rich_mask):
        return 0.0
    return float(chose_sing[sparse_mask].mean() - chose_sing[rich_mask].mean())

# name: prior_multi_singleton_max_feature_probe_rating
# description: Mean second_rating on prior trials (heard is NaN) with at least two unique singletons where second_probe is the singleton with the highest feature count.
def test_statistic(df):
    prior_df = df[df["heard"].isna()]
    if prior_df.empty:
        return 0.0
    unique_objs = prior_df["objects"].unique()
    max_sing_map = {}
    for obj_str in unique_objs:
        objs = np.asarray(json.loads(obj_str), dtype=int)
        diff = np.abs(objs[:, None, :] - objs[None, :, :]).sum(axis=2)
        is_sing = (diff == 0).sum(axis=1) == 1
        if is_sing.sum() >= 2:
            sing_idx = np.where(is_sing)[0]
            fcnt = objs.sum(axis=1)
            max_f = fcnt[sing_idx].max()
            max_sing_map[obj_str] = int([i for i in sing_idx if fcnt[i] == max_f][0])
    if not max_sing_map:
        return 0.0
    max_target = prior_df["objects"].map(lambda s: max_sing_map.get(s, -1)).to_numpy()
    mask = prior_df["second_probe"].to_numpy() == max_target
    if not np.any(mask):
        return 0.0
    return float(prior_df["second_rating"].to_numpy()[mask].astype(float).mean())
